class SearchResults {
  constructor(documents) {
    this.documents = documents;
  }

  get length() {
    return this.documents.length;
  }
}

class Searcher {
  constructor(documents) {
    this.documents = documents;
  }

  search(query) {
    if (query && typeof query.matches === "function") {
      return new SearchResults(this.documents.filter((document) => query.matches(document)));
    }

    return new SearchResults([]);
  }
}

class Writer {
  constructor(index) {
    this.index = index;
    this.pendingDocuments = [];
  }

  addDocument(document) {
    this.pendingDocuments.push({ ...document });
  }

  commit() {
    this.index.documents.push(...this.pendingDocuments);
    this.pendingDocuments = [];
  }
}

class Index {
  constructor(directory, schema) {
    this.directory = directory;
    this.schema = schema;
    this.documents = [];
  }

  writer() {
    return new Writer(this);
  }

  searcher() {
    return new Searcher(this.documents.slice());
  }
}

export function createIn(directory, schema) {
  return new Index(directory, schema);
}

export function create_in(directory, schema) {
  return createIn(directory, schema);
}

